// Central configuration for the whole workflow. Change values here only.
return [{
  json: {
    db: {"projects":"703c687e-5b91-4d88-b18e-ce10bd98c751","contacts":"79591305-b20f-4038-9623-9020050f4bc7","employees":"081a6e1c-e068-4ab4-a753-10a633ebf407","costs":"09030666-e6a9-4c82-a663-edd5effa8f3b","summary":"40ad5c8b-6d53-8196-88e5-cd493ad54296","orders":"62e33349-a8fb-4750-a77b-756d6940002e"},                         // Notion database ids (written by scripts/notion-setup.mjs)
    notionVersion: '2022-06-28',
    companyDomain: 'kevinbuild.co',             // emails from this domain are staff, not suppliers
    baseCurrency: 'USD',
    dateOrder: 'MDY',                           // how to read 03/04/2026 when both parts are <= 12
    timezone: 'America/New_York',
    highValueThreshold: 25000,                  // costs at/above this are flagged for approval
    maxUploadBytes: 5 * 1024 * 1024,            // Notion free plan file upload limit
    demoMode: true,                             // true: every email goes to demoRecipient with a "This is a demo" banner
    demoRecipient: 'samisiam851@gmail.com',
    senderEmail: 'samisiam851@gmail.com',
    intakeAddress: 'samisiam851+costs@gmail.com',
  },
}];

// Turns each incoming email (IMAP trigger or test webhook) into one item per document:
// every PDF/photo attachment becomes its own item; an email without attachments is one item (body only).
const cfg = $('Settings').first().json;
const fromWebhook = $('Test Intake Webhook').isExecuted;
const emails = fromWebhook ? $('Test Intake Webhook').all() : $('Email Trigger (IMAP)').all();

function addressOf(v) {
  if (!v) return { email: '', name: '' };
  if (typeof v === 'string') {
    const m = v.match(/^\s*"?([^"<]*)"?\s*<([^>]+)>/);
    return m ? { name: m[1].trim(), email: m[2].trim().toLowerCase() } : { name: '', email: v.trim().toLowerCase() };
  }
  const first = (v.value && v.value[0]) || {};
  return { name: first.name || '', email: String(first.address || '').toLowerCase() };
}
function stripHtml(html) {
  return String(html || '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|tr|li)>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
}
function bytesOf(b) {
  if (!b) return null;
  if (typeof b.bytes === 'number') return b.bytes;
  const m = String(b.fileSize || '').match(/([\d.]+)\s*(B|kB|KB|MB|GB)/);
  if (!m) return b.data && b.data.length > 100 ? Math.floor(b.data.length * 0.75) : null;
  return Math.round(+m[1] * { B: 1, kB: 1e3, KB: 1e3, MB: 1e6, GB: 1e9 }[m[2]]);
}
function kindOf(name, mime) {
  if (/pdf/i.test(mime) || /\.pdf$/i.test(name)) return 'pdf';
  if (/^image\//i.test(mime) || /\.(png|jpe?g|heic|webp|gif|tiff?)$/i.test(name)) return 'image';
  return 'other';
}

const out = [];
for (const item of emails) {
  const e = fromWebhook ? item.json.body || {} : item.json;
  const from = addressOf(e.from);
  const email = {
    from: from.email,
    fromName: e.fromName || from.name,
    subject: String(e.subject || '').trim(),
    text: String(e.text || stripHtml(e.html || e.textAsHtml) || '').trim(),
    date: e.date || new Date().toISOString(),
    messageId: e.messageId || e['message-id'] || null,
  };
  if (/^\[DEMO\]/.test(email.subject)) continue; // never re-process our own notifications

  const attachments = [];
  if (fromWebhook) {
    for (const a of e.attachments || []) {
      const buffer = Buffer.from(a.base64 || '', 'base64');
      let binary;
      try { binary = await this.helpers.prepareBinaryData(buffer, a.fileName, a.mimeType); }
      catch (err) { binary = { data: a.base64, mimeType: a.mimeType, fileName: a.fileName }; }
      attachments.push({ fileName: a.fileName, mimeType: a.mimeType, sizeBytes: buffer.length, binary });
    }
  } else {
    for (const b of Object.values(item.binary || {})) attachments.push({ fileName: b.fileName, mimeType: b.mimeType, sizeBytes: bytesOf(b), binary: b });
  }
  // Ignore tiny inline images (email signatures / logos).
  const docs = attachments
    .map((a) => ({ ...a, kind: kindOf(a.fileName || '', a.mimeType || '') }))
    .filter((a) => !(a.kind === 'image' && a.sizeBytes !== null && a.sizeBytes < 8000 && /^(image\d+|logo|signature)/i.test(a.fileName || '')));

  const base = { email, docCount: Math.max(docs.length, 1) };
  if (!docs.length) out.push({ json: { ...base, docIndex: 0, attachment: null, hasPdf: false, submissionId: (email.messageId || email.subject) + '#body' } });
  docs.forEach((a, i) => out.push({
    json: { ...base, docIndex: i, hasPdf: a.kind === 'pdf', attachment: { fileName: a.fileName, mimeType: a.mimeType, kind: a.kind, sizeBytes: a.sizeBytes }, submissionId: (email.messageId || email.subject) + '#' + i },
    binary: { document: a.binary },
  }));
}
return out;

// Rule-based extraction + supplier/project matching (logic in src/lib, appended below).
function run() {
  const cfg = $('Settings').first().json;
  const doc = $('Current Document').first().json;
  const input = $input.first().json;
  const documentText = doc.hasPdf && typeof input.text === 'string' ? input.text : '';
  const ref = toReferenceData({
    projects: flattenQueryResults($('Get Projects').all()),
    contacts: flattenQueryResults($('Get Suppliers').all()),
    employees: flattenQueryResults($('Get Employees').all()),
    orders: flattenQueryResults($('Get Purchase Orders').all()),
  });
  const parsed = prepareSubmission({ email: doc.email, attachment: doc.attachment, documentText }, ref, cfg);
  parsed.dedupeKey = buildDedupeKey(parsed); // looked up by the next Notion query
  return [{ json: { ...doc, documentTextPreview: documentText.slice(0, 1500), parsed } }];
}


// ===== Shared helpers below are generated from src/lib/*.cjs - edit there and run `npm run build` =====
// ---- src/lib/extract.cjs ----
// Rule-based field extraction for receipts / invoices.
// Pure functions only: this file is inlined into n8n Code nodes by scripts/build-workflow.mjs
// and unit-tested directly with node:test.

const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };

const CURRENCY_CODES = ['USD', 'AUD', 'EUR', 'GBP', 'CAD', 'NZD'];
const CURRENCY_SYMBOLS = [
  ['US$', 'USD'], ['A$', 'AUD'], ['AU$', 'AUD'], ['C$', 'CAD'], ['CA$', 'CAD'], ['NZ$', 'NZD'],
  ['€', 'EUR'], ['£', 'GBP'],
];

const DATE_PATTERN =
  '\\d{4}-\\d{1,2}-\\d{1,2}' +
  '|\\d{1,2}[\\/.\\-]\\d{1,2}[\\/.\\-]\\d{2,4}' +
  '|\\d{1,2}(?:st|nd|rd|th)?\\s+[A-Za-z]{3,9}\\.?,?\\s+\\d{4}' +
  '|[A-Za-z]{3,9}\\.?\\s+\\d{1,2}(?:st|nd|rd|th)?,?\\s+\\d{4}';

const AMOUNT_PATTERN = '(?:[A-Z]{3}\\s*)?(?:US\\$|AU\\$|A\\$|CA\\$|C\\$|NZ\\$|[$€£])?\\s*-?\\d{1,3}(?:,\\d{3})+(?:\\.\\d{1,2})?(?:\\s*[A-Z]{3})?|(?:[A-Z]{3}\\s*)?(?:US\\$|AU\\$|A\\$|CA\\$|C\\$|NZ\\$|[$€£])?\\s*-?\\d+(?:\\.\\d{1,2})?(?:\\s*[A-Z]{3})?';

function cleanText(s) {
  return String(s || '')
    .replace(/\r/g, '')
    .replace(/ /g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// Some PDF text extractors return a page as one long line. Re-insert breaks before
// the labels we rely on so the line-based rules still work.
function restoreLineBreaks(text) {
  const t = String(text || '');
  if ((t.match(/\n/g) || []).length >= 3 || t.length < 120) return t;
  return t.replace(
    /\s+(?=(?:Tax\s+)?Invoice\s+(?:No|Number|#|Date|Total)|Receipt\s+(?:No|Number|#|Date)|Invoice\s*#|Date\s*:|Due\s+Date|Payment\s+Due|Bill\s+To|Ship\s+To|Job\s*:|Site\s*:|Project\s*:|Purchase\s+Order|PO\s*(?:No|#|:)|Description\s*:|Sub\s*-?total|Tax\s*:|GST\s*:|Total|Amount|Balance\s+Due|Terms|Payment\s+received|Value\s*:)/gi,
    '\n'
  );
}

function escapeRx(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function pad2(n) {
  return String(n).padStart(2, '0');
}

function toISODate(y, m, d) {
  if (y < 100) y += 2000;
  if (!(m >= 1 && m <= 12 && d >= 1 && d <= 31 && y >= 2000 && y <= 2100)) return null;
  const dt = new Date(Date.UTC(y, m - 1, d));
  if (dt.getUTCMonth() !== m - 1) return null; // e.g. 31 Feb
  return `${y}-${pad2(m)}-${pad2(d)}`;
}

// dateOrder: 'MDY' (US) or 'DMY'. Only used when both numbers are <= 12.
function parseDate(str, dateOrder) {
  if (!str) return null;
  const s = String(str).trim();
  let m = s.match(/\b(\d{4})-(\d{1,2})-(\d{1,2})\b/);
  if (m) return toISODate(+m[1], +m[2], +m[3]);
  m = s.match(/\b(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]{3,9})\.?,?\s+(\d{4})\b/);
  if (m && MONTHS[m[2].slice(0, 3).toLowerCase()]) return toISODate(+m[3], MONTHS[m[2].slice(0, 3).toLowerCase()], +m[1]);
  m = s.match(/\b([A-Za-z]{3,9})\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})\b/);
  if (m && MONTHS[m[1].slice(0, 3).toLowerCase()]) return toISODate(+m[3], MONTHS[m[1].slice(0, 3).toLowerCase()], +m[2]);
  m = s.match(/\b(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})\b/);
  if (m) {
    const a = +m[1], b = +m[2], y = +m[3];
    if (a > 12) return toISODate(y, b, a);
    if (b > 12) return toISODate(y, a, b);
    return dateOrder === 'DMY' ? toISODate(y, b, a) : toISODate(y, a, b);
  }
  return null;
}

function addDays(iso, days) {
  const d = new Date(iso + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

function parseAmount(str) {
  const m = String(str || '').match(/-?\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|-?\d+(?:\.\d{1,2})?/);
  if (!m) return null;
  const n = Number(m[0].replace(/,/g, ''));
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : null;
}

// Detect a currency from a snippet such as "$8,450.00 USD", "€1.200", "AUD 300".
function detectCurrency(snippet) {
  const s = String(snippet || '');
  const code = s.match(new RegExp('\\b(' + CURRENCY_CODES.join('|') + ')\\b'));
  if (code) return code[1];
  for (const [sym, cur] of CURRENCY_SYMBOLS) if (s.includes(sym)) return cur;
  if (s.includes('$')) return null; // plain "$" is ambiguous -> caller applies the base currency
  return null;
}

function lines(text) {
  return cleanText(text).split('\n').map((l) => l.trim()).filter(Boolean);
}

// Find "<label> [:#-] value" on a line (value may also sit on the next line).
// labels are regex sources; returns { value, line } of the first match in priority order.
function findLabeled(text, labels, valuePattern, opts) {
  const ls = lines(text);
  const skipLine = opts && opts.skipLine;
  const sep = opts && opts.requireSep ? '\\s*[:#\\-]\\s*' : '\\s*(?:no\\.?|number|num|#)?\\s*[:#\\-]?\\s*';
  for (const label of labels) {
    const rx = new RegExp('(?:^|[^A-Za-z])(?:' + label + ')' + sep + '(.*)$', 'i');
    for (let i = 0; i < ls.length; i++) {
      if (skipLine && skipLine.test(ls[i])) continue;
      const m = ls[i].match(rx);
      if (!m) continue;
      const vrx = new RegExp(valuePattern, 'i');
      let v = m[1].match(vrx);
      if (!v && i + 1 < ls.length && !m[1].trim()) v = ls[i + 1].match(vrx);
      if (v) return { value: v[0].trim(), line: ls[i], label };
    }
  }
  return null;
}

function looksLikeDate(token) {
  return /^\d{4}-\d{1,2}-\d{1,2}$|^\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}$/.test(token);
}

function extractDocRef(sources) {
  const labels = [
    'tax invoice', 'invoice', 'inv', 'receipt', 'rcpt', 'bill', 'credit note', 'statement', 'document', 'reference', 'ref',
  ];
  const token = '[A-Z0-9][A-Z0-9\\-\\/_.]*\\d[A-Z0-9\\-\\/_]*';
  for (const src of sources) {
    for (const label of labels) {
      const rx = new RegExp('(?:^|[^A-Za-z])(?:' + label + ')\\b\\.?\\s*(?:no\\.?|number|num|#)?\\s*[:#]?\\s*(' + token + ')', 'i');
      const m = String(src || '').match(rx);
      if (m && !looksLikeDate(m[1]) && !/^\d{1,2}$/.test(m[1])) return m[1].replace(/[.,;:]+$/, '').toUpperCase();
    }
  }
  // Unlabelled but obviously a reference, e.g. "INV-78102" or "CH-INV-9910".
  for (const src of sources) {
    const m = String(src || '').match(/\b(?:[A-Z]{1,4}-)?(?:INV|RCT|RCPT|REC|BILL)-?\d{3,}\b/i);
    if (m) return m[0].toUpperCase();
  }
  return null;
}

function extractPO(text) {
  const t = String(text || '');
  const m =
    t.match(/\b(?:PO|P\.O\.|purchase\s+order)\b\s*(?:no\.?|number|#)?\s*[:#]?\s*((?:PO-)?[A-Z0-9]*\d[A-Z0-9\-]*)/i) ||
    t.match(/\b(PO-?\d{3,})\b/i);
  if (!m) return null;
  const v = m[1].toUpperCase();
  return v.startsWith('PO-') ? v : 'PO-' + v.replace(/^PO/, '');
}

function extractDocType(text) {
  const t = String(text || '').toLowerCase();
  if (/credit note/.test(t)) return 'Credit note';
  if (/\b(tax )?invoice\b/.test(t)) return 'Invoice';
  if (/\breceipt\b/.test(t)) return 'Receipt';
  if (/\bstatement\b/.test(t)) return 'Statement';
  return 'Document';
}

const AMOUNT_LABELS = [
  ['(?:amount|balance|total)\\s+(?:due|owing|payable)', 'due'],
  ['amount\\s+payable', 'due'],
  ['grand\\s+total', 'total'],
  ['invoice\\s+total', 'total'],
  ['total\\s+amount', 'total'],
  ['total\\s+(?:\\(?inc[a-z.]*\\)?\\s*(?:gst|tax|vat)?)', 'total'],
  ['amount\\s+paid|total\\s+paid|paid\\s+amount', 'paid'],
  ['(?<![A-Za-z])total(?!\\s*(?:ex|excl|before))', 'total'],
  ['amount', 'total'],
];

function extractAmounts(text) {
  const out = [];
  const ls = lines(text);
  for (const [label, kind] of AMOUNT_LABELS) {
    const rx = new RegExp('(?<![A-Za-z])(?:sub)?(' + label + ')[^\\n\\d$€£]{0,25}?(' + AMOUNT_PATTERN + ')', 'i');
    for (const line of ls) {
      if (/\bsub\s*-?total\b/i.test(line) && !/grand/i.test(line)) continue;
      const m = line.match(rx);
      if (!m) continue;
      const amount = parseAmount(m[2]);
      if (amount === null) continue;
      out.push({ amount, kind, currency: detectCurrency(m[2]) || detectCurrency(line), line });
    }
  }
  return out;
}

// Fallback for short, unstructured emails: "Home Depot receipt #4471 $245.10".
function extractLooseAmount(text) {
  const rx = /(?:US\$|AU\$|A\$|CA\$|C\$|NZ\$|[$€£])\s*(\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\d+(?:\.\d{1,2})?)|\b(\d{1,3}(?:,\d{3})+(?:\.\d{2})|\d+\.\d{2})\s*(USD|AUD|EUR|GBP|CAD|NZD)\b|\b(USD|AUD|EUR|GBP|CAD|NZD)\s*(\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\d+(?:\.\d{1,2})?)/g;
  const found = new Map();
  let m;
  while ((m = rx.exec(String(text || '')))) {
    const amount = parseAmount(m[1] || m[2] || m[5]);
    if (amount === null) continue;
    found.set(amount, detectCurrency(m[0]));
  }
  if (found.size !== 1) return null;
  const [[amount, currency]] = [...found.entries()];
  return { amount, currency, kind: 'loose' };
}

function extractStatus(text, amounts) {
  const t = String(text || '');
  const dueZero = amounts.find((a) => a.kind === 'due' && a.amount === 0);
  const duePositive = amounts.find((a) => a.kind === 'due' && a.amount > 0);
  const paidPositive = amounts.find((a) => a.kind === 'paid' && a.amount > 0);
  if (/\b(unpaid|not\s+paid|overdue|outstanding|awaiting\s+payment)\b/i.test(t) && !dueZero) {
    return paidPositive ? 'Partially Paid' : 'Unpaid';
  }
  if (/\b(partial(ly)?\s+paid|part\s+payment|partial\s+payment|deposit\s+paid)\b/i.test(t)) return 'Partially Paid';
  if (paidPositive && duePositive) return 'Partially Paid';
  if (dueZero) return 'Paid';
  if (/\b(paid\s+in\s+full|payment\s+received|thank\s+you\s+for\s+your\s+payment|status\s*:\s*paid|paid\s+(?:by|on|with|via)\s+(?:the\s+)?(?:company\s+)?(?:card|credit\s+card|cash|cheque|check|eftpos|visa|mastercard|amex|wire|transfer|bank\s+transfer))\b/i.test(t)) return 'Paid';
  if (/(^|\n)\s*\**\s*PAID\s*\**\s*($|\n)/.test(t)) return 'Paid'; // a "PAID" stamp on its own line
  if (paidPositive) return 'Paid';
  if (duePositive || /\b(due\s+date|payment\s+due|please\s+pay|net\s*\d{1,3}|due\s+on\s+receipt|remit\s+to)\b/i.test(t)) return 'Unpaid';
  if (/\breceipt\b/i.test(t) && !/\binvoice\b/i.test(t)) return 'Paid'; // a plain receipt is proof of payment
  return 'Unknown';
}

function extractDates(text, dateOrder) {
  const dueLine = /\b(due|pay\s+by|payable\s+by|expires?)\b/i;
  const docLabel = findLabeled(
    text,
    ['invoice\\s+date', 'receipt\\s+date', 'date\\s+of\\s+issue', 'issue\\s+date', 'issued(?:\\s+on)?', 'tax\\s+date', 'transaction\\s+date', 'date'],
    DATE_PATTERN,
    { skipLine: dueLine }
  );
  let docDate = docLabel ? parseDate(docLabel.value, dateOrder) : null;
  if (!docDate) {
    for (const line of lines(text)) {
      if (dueLine.test(line)) continue;
      const m = line.match(new RegExp(DATE_PATTERN));
      if (m && (docDate = parseDate(m[0], dateOrder))) break;
    }
  }
  const dueLabel = findLabeled(text, ['payment\\s+due(?:\\s+date)?', 'due\\s+date', 'due\\s+by', 'pay\\s+by', 'payable\\s+by', 'due'], DATE_PATTERN);
  let dueDate = dueLabel ? parseDate(dueLabel.value, dateOrder) : null;
  let dueSource = dueDate ? 'document' : null;
  if (!dueDate && docDate) {
    const net = String(text || '').match(/\bnet\s*(\d{1,3})\b/i) || String(text || '').match(/\b(\d{1,3})\s+days?\s+(?:from|after)\s+(?:invoice|date)/i);
    if (net) { dueDate = addDays(docDate, +net[1]); dueSource = 'terms'; }
    else if (/\bdue\s+on\s+receipt\b/i.test(text)) { dueDate = docDate; dueSource = 'terms'; }
  }
  return { docDate, dueDate, dueSource };
}

function extractLabeledSupplier(text) {
  const hit = findLabeled(text, ['supplier', 'vendor', 'merchant', 'store', 'sold\\s+by', 'from'], '[A-Za-z0-9&][^\\n]{1,60}', { requireSep: true });
  return hit ? hit.value.replace(/\s{2,}.*/, '').trim() : null;
}

function extractDescription(text) {
  const hit = findLabeled(text, ['description'], '[A-Za-z0-9][^\\n]{2,80}', { requireSep: true });
  return hit ? hit.value.trim() : null;
}

/**
 * Main entry point.
 * @param {{subject:string, body:string, documentText:string}} input
 * @param {{baseCurrency:string, dateOrder:string}} cfg
 */
function extractFields(input, cfg) {
  const subject = cleanText(input.subject);
  const body = cleanText(input.body);
  const doc = cleanText(restoreLineBreaks(input.documentText));
  // Document text is the primary source; the email body/subject fill gaps.
  const primary = doc || body;
  const all = [doc, subject, body].filter(Boolean).join('\n');

  const docRef = extractDocRef([doc, subject, body]);
  let amounts = extractAmounts(primary);
  if (!amounts.length && doc) amounts = extractAmounts(body);
  // Pick the amount: prefer the invoice total; if only "balance due 0" exists, fall back to the paid/total line.
  let chosen =
    amounts.find((a) => a.kind === 'total' && a.amount > 0) ||
    amounts.find((a) => a.kind === 'due' && a.amount > 0) ||
    amounts.find((a) => a.kind === 'paid' && a.amount > 0) ||
    null;
  let amountMethod = chosen ? 'labelled' : null;
  if (!chosen) {
    chosen = extractLooseAmount(primary) || extractLooseAmount(all);
    if (chosen) amountMethod = 'unlabelled';
  }

  let currency = (chosen && chosen.currency) || null;
  let currencyMethod = currency ? 'amount' : null;
  if (!currency) {
    const c = String(all).match(/\bcurrency\s*[:\-]?\s*([A-Z]{3})\b/i);
    if (c) { currency = c[1].toUpperCase(); currencyMethod = 'label'; }
  }
  if (!currency) {
    const codes = new Set((all.match(new RegExp('\\b(' + CURRENCY_CODES.join('|') + ')\\b', 'g')) || []));
    if (codes.size === 1) { currency = [...codes][0]; currencyMethod = 'text'; }
  }
  if (!currency) { currency = cfg.baseCurrency; currencyMethod = 'default'; }

  const { docDate, dueDate, dueSource } = extractDates(primary, cfg.dateOrder);
  const status = extractStatus(all, amounts);
  const docType = extractDocType(doc || subject + '\n' + body);

  return {
    docRef,
    docType,
    poNumber: extractPO(all),
    amount: chosen ? chosen.amount : null,
    amountMethod,
    currency,
    currencyMethod,
    status,
    docDate,
    dueDate,
    dueSource,
    labeledSupplier: extractLabeledSupplier(doc || body),
    description: extractDescription(doc) || null,
    firstLine: lines(doc)[0] || null,
  };
}


// ---- src/lib/match.cjs ----
// Matching an extracted document to a Supplier (Contacts) and a Project.
// Pure functions; inlined into n8n Code nodes and unit-tested.

const GENERIC_EMAIL_DOMAINS = [
  'gmail.com', 'googlemail.com', 'outlook.com', 'hotmail.com', 'live.com', 'yahoo.com', 'icloud.com', 'me.com',
  'aol.com', 'proton.me', 'protonmail.com', 'example.com',
];
const GENERIC_PROJECT_WORDS = [
  'home', 'house', 'residence', 'development', 'renovation', 'extension', 'fit', 'out', 'fitout', 'cafe', 'café',
  'project', 'build', 'new', 'the', 'and', 'street', 'court', 'view', 'job', 'site',
];
const ADDRESS_ABBREVIATIONS = [
  [/\bdrive\b/g, 'dr'], [/\bstreet\b/g, 'st'], [/\bavenue\b/g, 'ave'], [/\broad\b/g, 'rd'], [/\bcourt\b/g, 'ct'],
  [/\bplace\b/g, 'pl'], [/\blane\b/g, 'ln'], [/\bboulevard\b/g, 'blvd'],
];

function normalizeText(s) {
  let t = String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  t = t.replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, ' ').trim();
  for (const [rx, short] of ADDRESS_ABBREVIATIONS) t = t.replace(rx, short);
  return t;
}

function containsPhrase(haystackNorm, phrase) {
  const p = normalizeText(phrase);
  if (!p) return -1;
  const idx = (' ' + haystackNorm + ' ').indexOf(' ' + p + ' ');
  return idx;
}

function emailDomain(email) {
  const m = String(email || '').toLowerCase().match(/@([a-z0-9.\-]+)$/);
  return m ? m[1] : null;
}

/**
 * contacts: [{id, name, company, email, type}] (suppliers / subcontractors only)
 * employees: [{id, name, email, role}]
 */
function matchSupplier(input, contacts, employees, cfg) {
  const fromEmail = String(input.fromEmail || '').toLowerCase();
  const domain = emailDomain(fromEmail);
  const internal = !!domain && domain === String(cfg.companyDomain || '').toLowerCase();
  const submittedBy = internal ? employees.find((e) => String(e.email || '').toLowerCase() === fromEmail) || null : null;

  const result = (contact, method) => ({
    contactId: contact ? contact.id : null,
    name: contact ? contact.name : null,
    method,
    internalSender: internal,
    submittedBy: submittedBy ? { id: submittedBy.id, name: submittedBy.name, email: submittedBy.email } : null,
  });

  if (!internal && fromEmail) {
    const exact = contacts.find((c) => String(c.email || '').toLowerCase() === fromEmail);
    if (exact) return result(exact, 'sender email');
    const generic = (cfg.genericDomains || GENERIC_EMAIL_DOMAINS).includes(domain);
    if (domain && !generic) {
      const byDomain = contacts.filter((c) => emailDomain(c.email) === domain);
      if (byDomain.length === 1) return result(byDomain[0], 'sender domain');
    }
  }

  // Look for a known supplier name in the document (document text first, then email).
  const docNorm = normalizeText(input.documentText);
  const restNorm = normalizeText([input.labeledSupplier, input.subject, input.body, internal ? '' : input.fromName].join(' '));
  for (const [hay, method] of [[normalizeText(input.labeledSupplier), 'supplier label'], [docNorm, 'document text'], [restNorm, 'email text']]) {
    if (!hay) continue;
    let best = null;
    for (const c of contacts) {
      for (const n of [c.name, c.company]) {
        if (!n || normalizeText(n).length < 4) continue;
        const idx = containsPhrase(hay, n);
        if (idx >= 0 && (!best || idx < best.idx)) best = { idx, c };
      }
    }
    if (best) return result(best.c, method);
  }

  // Unknown supplier: best-effort name so the record is still useful, flagged for review.
  const unknown = result(null, 'unknown');
  unknown.name =
    input.labeledSupplier ||
    merchantFromText(input.body) ||
    (!internal && input.fromName ? input.fromName : null) ||
    input.firstLine ||
    (!internal && domain ? domain : null) ||
    'Unknown supplier';
  unknown.name = String(unknown.name).slice(0, 80).trim();
  return unknown;
}

// "Picked up fixings at Home Depot for the Skyline job" -> "Home Depot"
function merchantFromText(text) {
  const m = String(text || '').match(/\b(?:at|from)\s+([A-Z][A-Za-z0-9&'.\-]*(?:\s+(?:&\s+)?[A-Z][A-Za-z0-9&'.\-]*){0,3})/);
  if (!m) return null;
  const name = m[1].trim();
  if (/^(Kevin|The|Site|Job|Project)\b/.test(name)) return null;
  return name;
}

function codeRegex(code) {
  const m = String(code || '').toUpperCase().match(/^([A-Z]+)[\s\-]?(\d+)$/);
  if (!m) return new RegExp('\\b' + String(code).replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i');
  return new RegExp('\\b' + m[1] + '[\\s\\-]?0*' + String(+m[2]) + '\\b', 'i');
}

function distinctiveWord(name, allProjects) {
  const words = normalizeText(name).split(' ').filter((w) => w.length >= 4 && !GENERIC_PROJECT_WORDS.includes(w));
  const w = words[0];
  if (!w) return null;
  const clash = allProjects.filter((p) => normalizeText(p.name).split(' ').includes(w));
  return clash.length === 1 ? w : null;
}

/**
 * projects: [{id, name, code, address, stage, pmId}]
 * orders:   [{id, po, projectId}]
 * Returns the strongest match tier; ambiguous if >1 project at that tier.
 */
function matchProject(input, projects, orders) {
  const raw = [input.subject, input.body, input.documentText].join('\n');
  const norm = normalizeText(raw);
  const tiers = [
    ['project code', (p) => p.code && codeRegex(p.code).test(raw)],
    ['purchase order', (p) => input.poNumber && orders.some((o) => o.po && o.po.toUpperCase() === input.poNumber && o.projectId === p.id)],
    ['project name', (p) => containsPhrase(norm, p.name) >= 0],
    ['site address', (p) => p.address && containsPhrase(norm, p.address) >= 0],
    ['project keyword', (p) => { const w = distinctiveWord(p.name, projects); return !!w && containsPhrase(norm, w) >= 0; }],
  ];
  for (const [method, test] of tiers) {
    const hits = projects.filter(test);
    if (hits.length === 1) return { project: hits[0], method, candidates: [] };
    if (hits.length > 1) return { project: null, method: 'ambiguous (' + method + ')', candidates: hits.map((h) => h.name) };
  }
  return { project: null, method: 'none', candidates: [] };
}


// ---- src/lib/notion.cjs ----
// Small helpers for reading/writing Notion page properties (API version 2022-06-28).

const COST = {
  title: 'Description',
  supplier: 'Supplier',
  supplierContact: 'Supplier Contact',
  docRef: 'Document Ref',
  docDate: 'Document Date',
  amount: 'Amount',
  currency: 'Currency',
  status: 'Payment Status',
  due: 'Payment Due',
  project: 'Project',
  document: 'Document',
  dedupeKey: 'Dedupe Key',
  summaryKey: 'Summary Key',
  needsReview: 'Needs Review',
  reviewReason: 'Review Reason',
  sourceEmail: 'Source Email',
  messageId: 'Source Message ID',
  receivedAt: 'Received At',
  submissions: 'Submission Count',
  updateLog: 'Update Log',
};

function richText(text) {
  const s = String(text == null ? '' : text);
  if (!s) return [];
  const chunks = [];
  for (let i = 0; i < s.length && chunks.length < 50; i += 2000) chunks.push({ type: 'text', text: { content: s.slice(i, i + 2000) } });
  return chunks;
}

function readProp(p) {
  if (!p) return null;
  switch (p.type) {
    case 'title':
    case 'rich_text':
      return p[p.type].map((t) => t.plain_text).join('') || null;
    case 'select':
    case 'status':
      return p[p.type] ? p[p.type].name : null;
    case 'number':
      return p.number;
    case 'email':
      return p.email;
    case 'phone_number':
      return p.phone_number;
    case 'checkbox':
      return p.checkbox;
    case 'date':
      return p.date ? p.date.start : null;
    case 'relation':
      return p.relation.map((r) => r.id);
    case 'files':
      return p.files.map((f) => f.name);
    case 'formula':
      return p.formula[p.formula.type];
    default:
      return null;
  }
}

function readCostPage(page) {
  const P = page.properties || {};
  const g = (k) => readProp(P[COST[k]]);
  return {
    id: page.id,
    url: page.url,
    title: g('title'),
    supplierName: g('supplier'),
    supplierContactId: (g('supplierContact') || [])[0] || null,
    docRef: g('docRef'),
    docDate: g('docDate'),
    amount: g('amount'),
    currency: g('currency'),
    status: g('status'),
    dueDate: g('due'),
    projectId: (g('project') || [])[0] || null,
    dedupeKey: g('dedupeKey'),
    summaryKey: g('summaryKey'),
    needsReview: !!g('needsReview'),
    reviewReason: g('reviewReason'),
    updateLog: g('updateLog'),
    submissions: g('submissions') || 1,
    receivedAt: g('receivedAt'),
  };
}

function flattenQueryResults(items) {
  const out = [];
  for (const it of items) {
    const j = it && it.json ? it.json : it;
    if (j && Array.isArray(j.results)) out.push(...j.results);
  }
  return out;
}


// ---- src/lib/pipeline.cjs ----
// One call that turns an email + document text into a cost record ready for the
// duplicate check. Used by the "Parse & Match" Code node and the unit tests.
// Depends on extract.cjs, match.cjs, notion.cjs.

function toReferenceData(raw) {
  const rp = (page, name) => readProp(page.properties[name]);
  return {
    projects: (raw.projects || []).map((p) => ({
      id: p.id, name: rp(p, 'Project'), code: rp(p, 'Project Code'), address: rp(p, 'Site Address'),
      stage: rp(p, 'Stage'), pmId: (rp(p, 'Project Manager') || [])[0] || null,
    })),
    contacts: (raw.contacts || []).map((c) => ({ id: c.id, name: rp(c, 'Name'), company: rp(c, 'Company'), email: rp(c, 'Email'), type: rp(c, 'Type') })),
    employees: (raw.employees || []).map((e) => ({ id: e.id, name: rp(e, 'Name'), email: rp(e, 'Email'), role: rp(e, 'Role') })),
    orders: (raw.orders || []).map((o) => ({ id: o.id, po: rp(o, 'PO Number'), projectId: (rp(o, 'Project') || [])[0] || null })),
  };
}

/**
 * @param sub {{email:{from,fromName,subject,text,date,messageId}, attachment:{fileName,mimeType,kind,sizeBytes}|null, documentText:string}}
 * @param ref output of toReferenceData
 */
function prepareSubmission(sub, ref, cfg) {
  const email = sub.email || {};
  const attachment = sub.attachment || null;
  const documentText = sub.documentText || '';
  const f = extractFields({ subject: email.subject, body: email.text, documentText }, cfg);

  const supplier = matchSupplier(
    { fromEmail: email.from, fromName: email.fromName, subject: email.subject, body: email.text, documentText, labeledSupplier: f.labeledSupplier, firstLine: f.firstLine },
    ref.contacts, ref.employees, cfg
  );
  const pm = matchProject({ subject: email.subject, body: email.text, documentText, poNumber: f.poNumber }, ref.projects, ref.orders);
  const receivedAt = email.date ? new Date(email.date).toISOString() : new Date().toISOString();

  return {
    // extracted fields
    docRef: f.docRef,
    docType: f.docType,
    description: f.description,
    amount: f.amount,
    amountMethod: f.amountMethod,
    currency: f.currency,
    currencyMethod: f.currencyMethod,
    status: f.status,
    docDate: f.docDate || receivedAt.slice(0, 10),
    docDateSource: f.docDate ? 'document' : 'email',
    dueDate: f.dueDate,
    dueSource: f.dueSource,
    poNumber: f.poNumber,
    // matching
    supplierName: supplier.name,
    supplierContactId: supplier.contactId,
    supplierMethod: supplier.method,
    submittedBy: supplier.submittedBy,
    projectId: pm.project ? pm.project.id : null,
    projectName: pm.project ? pm.project.name : null,
    projectStage: pm.project ? pm.project.stage : null,
    projectPmId: pm.project ? pm.project.pmId : null,
    projectMethod: pm.method,
    projectCandidates: pm.candidates,
    // source
    fromEmail: email.from || null,
    fromName: email.fromName || null,
    subject: email.subject || '',
    messageId: email.messageId || null,
    receivedAt,
    sourceEmail: 'From: ' + (email.fromName ? email.fromName + ' <' + email.from + '>' : email.from || '?') + ' | Subject: ' + (email.subject || '') +
      ' | Received: ' + receivedAt + (attachment ? ' | File: ' + attachment.fileName : ' | No attachment'),
    attachmentKind: attachment ? attachment.kind : null,
    attachmentName: attachment ? attachment.fileName : null,
    pdfUnreadable: !!(attachment && attachment.kind === 'pdf' && !String(documentText).trim()),
    attachmentTooLarge: !!(attachment && attachment.sizeBytes && attachment.sizeBytes > cfg.maxUploadBytes),
  };
}

function findPeople(record, ref) {
  const project = record.projectId ? ref.projects.find((p) => p.id === record.projectId) : null;
  const pmId = record.projectPmId || (project ? project.pmId : null);
  const pick = (e) => (e ? { name: e.name, email: e.email } : null);
  return {
    projectManager: pick(pmId ? ref.employees.find((e) => e.id === pmId) : null),
    officeAdmin: pick(ref.employees.find((e) => e.role === 'Office Admin')),
    owner: pick(ref.employees.find((e) => e.role === 'Owner')),
  };
}


// ---- src/lib/decide.cjs ----
// Review rules, duplicate detection and create/update decisions.
// Depends on notion.cjs (COST, richText, readCostPage) - files are concatenated at build time.

const STATUS_RANK = { Unknown: 0, Unpaid: 1, 'Partially Paid': 2, Paid: 3 };

function lowerKey(s) {
  return String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
}

// Same shape as the keys already used in Part 2: "apex timber & frames|inv-77812".
function buildDedupeKey(r) {
  if (r.docRef) return lowerKey(r.supplierName) + '|' + lowerKey(r.docRef);
  return lowerKey(r.supplierName) + '|no-ref|' + (r.docDate || 'no-date') + '|' + (r.amount == null ? 'no-amount' : r.amount);
}

function summaryMonthOf(r) {
  return String(r.docDate || r.receivedAt || '').slice(0, 7) || null;
}

function buildSummaryKey(r) {
  const month = summaryMonthOf(r);
  if (!month) return null;
  return lowerKey(r.supplierName) + '|' + month + '|' + String(r.currency || '').toUpperCase();
}

function summaryTarget(r) {
  const key = r.summaryKey || buildSummaryKey(r);
  if (!key) return null;
  return { key, supplierName: r.supplierName, supplierContactId: r.supplierContactId || null, month: summaryMonthOf(r), currency: r.currency };
}

function money(n, cur) {
  if (n == null) return '-';
  return (cur ? cur + ' ' : '') + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

/** Rules that decide whether a (merged) cost record needs a human to look at it. */
function assessReview(r, cfg, today) {
  const reasons = [];
  if (r.amount == null) reasons.push('Amount not found');
  else if (r.amount <= 0) reasons.push('Zero or negative amount (credit note?)');
  if (!r.docRef) reasons.push('Invoice/receipt number not found - duplicate check falls back to supplier + date + amount');
  if (!r.docDate) reasons.push('Document date not found');
  else if (r.docDateSource === 'email') reasons.push('Document date not found - used email received date');
  if (!r.projectId) {
    reasons.push(r.projectCandidates && r.projectCandidates.length
      ? 'Several projects matched (' + r.projectCandidates.join(', ') + ') - pick the right one'
      : 'No project matched - add the project code (e.g. RIV-001) to the email');
  } else if (r.projectStage === 'Completed') reasons.push('Project "' + r.projectName + '" is marked Completed');
  if (r.supplierMethod === 'unknown') reasons.push('Supplier "' + r.supplierName + '" is not in Contacts (new supplier?)');
  if (r.status === 'Unknown') reasons.push('Payment status unclear - counted as unpaid');
  if (r.currency && r.currency !== cfg.baseCurrency) reasons.push('Currency is ' + r.currency + ' (not ' + cfg.baseCurrency + ')');
  if (r.amount != null && r.amount >= cfg.highValueThreshold) reasons.push('High value (>= ' + money(cfg.highValueThreshold, cfg.baseCurrency) + ') - check approval');
  if (r.status !== 'Paid' && r.dueDate && r.dueDate < today) reasons.push('Unpaid and overdue (due ' + r.dueDate + ')');
  if (r.attachmentKind === 'image') reasons.push('Photo/scanned receipt - no OCR, please check the fields manually');
  if (r.attachmentKind === 'other') reasons.push('Unsupported attachment type (' + (r.attachmentName || 'unknown') + ')');
  if (r.pdfUnreadable) reasons.push('PDF has no readable text (scanned?) - fields taken from the email only');
  if (r.attachmentTooLarge) reasons.push('Attachment larger than the Notion free-plan upload limit - not attached');
  return reasons;
}

function logLine(today, text) {
  return today + ' - ' + text;
}

function appendLog(existingLog, line) {
  const all = (existingLog ? existingLog + '\n' : '') + line;
  return all.length > 1900 ? '...' + all.slice(all.length - 1900) : all;
}

function costProperties(r, fields) {
  const P = {};
  const has = (k) => !fields || fields.includes(k);
  if (has('title')) P[COST.title] = { title: richText(r.title) };
  if (has('supplier')) P[COST.supplier] = { rich_text: richText(r.supplierName) };
  if (has('supplierContact')) P[COST.supplierContact] = { relation: r.supplierContactId ? [{ id: r.supplierContactId }] : [] };
  if (has('docRef')) P[COST.docRef] = { rich_text: richText(r.docRef) };
  if (has('docDate')) P[COST.docDate] = { date: r.docDate ? { start: r.docDate } : null };
  if (has('amount')) P[COST.amount] = { number: r.amount == null ? null : r.amount };
  if (has('currency')) P[COST.currency] = { select: r.currency ? { name: r.currency } : null };
  if (has('status')) P[COST.status] = { select: r.status ? { name: r.status } : null };
  if (has('dueDate')) P[COST.due] = { date: r.dueDate ? { start: r.dueDate } : null };
  if (has('project')) P[COST.project] = { relation: r.projectId ? [{ id: r.projectId }] : [] };
  if (has('dedupeKey')) P[COST.dedupeKey] = { rich_text: richText(r.dedupeKey) };
  if (has('summaryKey')) P[COST.summaryKey] = { rich_text: richText(r.summaryKey) };
  if (has('needsReview')) P[COST.needsReview] = { checkbox: !!r.needsReview };
  if (has('reviewReason')) P[COST.reviewReason] = { rich_text: richText(r.reviewReason) };
  if (has('sourceEmail')) P[COST.sourceEmail] = { rich_text: richText(r.sourceEmail) };
  if (has('messageId')) P[COST.messageId] = { rich_text: richText(r.messageId) };
  if (has('receivedAt')) P[COST.receivedAt] = { date: r.receivedAt ? { start: r.receivedAt } : null };
  if (has('submissions')) P[COST.submissions] = { number: r.submissions };
  if (has('updateLog')) P[COST.updateLog] = { rich_text: richText(r.updateLog) };
  return P;
}

/**
 * Decide what to do with a parsed submission.
 * @param parsed   output of the "Parse & Match" step (one document)
 * @param existingPage  Notion page with the same Dedupe Key, or null
 * @returns {{action:'create'|'update'|'duplicate', record, changes:string[], properties, recalc:string[], newReviewReasons:string[]}}
 */
function decideAction(parsed, existingPage, cfg, today) {
  const incoming = Object.assign({}, parsed);
  incoming.dedupeKey = buildDedupeKey(incoming);
  incoming.summaryKey = buildSummaryKey(incoming);

  if (!existingPage) {
    const reasons = assessReview(incoming, cfg, today);
    const record = Object.assign({}, incoming, {
      title: incoming.description || [incoming.docType, incoming.docRef, '-', incoming.supplierName].filter(Boolean).join(' '),
      needsReview: reasons.length > 0,
      reviewReason: reasons.join('; '),
      submissions: 1,
      updateLog: logLine(today, 'Created from email "' + (incoming.subject || '') + '" from ' + (incoming.fromEmail || 'unknown sender')),
    });
    return {
      action: 'create',
      record,
      changes: [],
      newReviewReasons: reasons,
      properties: costProperties(record),
      recalc: [summaryTarget(record)].filter(Boolean),
    };
  }

  const old = readCostPage(existingPage);
  if (!old.summaryKey) old.summaryKey = buildSummaryKey(old);
  const merged = Object.assign({}, old, {
    supplierMethod: parsed.supplierMethod === 'unknown' && old.supplierContactId ? 'existing' : parsed.supplierMethod,
    projectName: parsed.projectName,
    projectStage: parsed.projectStage,
    attachmentKind: parsed.attachmentKind,
    attachmentName: parsed.attachmentName,
    pdfUnreadable: parsed.pdfUnreadable,
    attachmentTooLarge: parsed.attachmentTooLarge,
    docDateSource: old.docDate ? 'document' : parsed.docDateSource,
  });
  const changes = [];
  const updateReasons = [];
  const changed = [];

  const setIf = (field, label, fmt) => {
    const nv = incoming[field];
    if (nv == null || nv === '' || nv === old[field]) return;
    changes.push(label + ': ' + (old[field] == null ? '(empty)' : fmt ? fmt(old[field]) : old[field]) + ' -> ' + (fmt ? fmt(nv) : nv));
    merged[field] = nv;
    changed.push(field);
  };

  if (incoming.amount != null && old.amount != null && incoming.amount !== old.amount) {
    updateReasons.push('Amount changed on resubmission: ' + money(old.amount) + ' -> ' + money(incoming.amount));
  }
  setIf('amount', 'Amount', (v) => money(v));
  if (incoming.currency && old.currency && incoming.currency !== old.currency && incoming.currencyMethod !== 'default') {
    updateReasons.push('Currency changed on resubmission: ' + old.currency + ' -> ' + incoming.currency);
    setIf('currency', 'Currency');
  } else if (!old.currency) setIf('currency', 'Currency');
  setIf('docDate', 'Document date');
  setIf('dueDate', 'Payment due');

  if (incoming.status && incoming.status !== 'Unknown' && incoming.status !== old.status) {
    if ((STATUS_RANK[incoming.status] || 0) >= (STATUS_RANK[old.status] || 0)) setIf('status', 'Payment status');
    else updateReasons.push('Newer document says "' + incoming.status + '" but record is "' + old.status + '" - kept "' + old.status + '"');
  }
  if (incoming.projectId && incoming.projectId !== old.projectId) {
    if (!old.projectId) { merged.projectId = incoming.projectId; changes.push('Project linked: ' + incoming.projectName); changed.push('project'); }
    else updateReasons.push('Resubmission points to a different project (' + incoming.projectName + ') - not changed');
  }
  if (!old.supplierContactId && incoming.supplierContactId) { merged.supplierContactId = incoming.supplierContactId; changed.push('supplierContact'); }

  merged.summaryKey = buildSummaryKey(merged);
  merged.submissions = (old.submissions || 1) + 1;
  merged.messageId = incoming.messageId;

  if (!changes.length && !updateReasons.length) {
    merged.updateLog = appendLog(old.updateLog, logLine(today, 'Duplicate submission ignored - no changes (' + (incoming.messageId || 'no message id') + ')'));
    return {
      action: 'duplicate',
      record: merged,
      changes: [],
      newReviewReasons: [],
      properties: costProperties(merged, ['submissions', 'updateLog', 'messageId']),
      recalc: [summaryTarget(merged)].filter(Boolean),
    };
  }

  const ruleReasons = assessReview(merged, cfg, today);
  const reasons = [...new Set([...updateReasons, ...ruleReasons])];
  merged.needsReview = old.needsReview || reasons.length > 0;
  merged.reviewReason = reasons.length ? reasons.join('; ') : old.reviewReason;
  merged.updateLog = appendLog(
    old.updateLog,
    logLine(today, 'Resubmission "' + (incoming.subject || '') + '": ' + (changes.length ? changes.join('; ') : 'no field changes') +
      (updateReasons.length ? ' | flagged: ' + updateReasons.join('; ') : ''))
  );
  return {
    action: 'update',
    record: merged,
    changes,
    newReviewReasons: reasons,
    properties: costProperties(merged, [...changed, 'summaryKey', 'needsReview', 'reviewReason', 'submissions', 'updateLog', 'messageId']),
    recalc: [summaryTarget(merged), old.summaryKey !== merged.summaryKey ? summaryTarget(old) : null].filter(Boolean),
  };
}


return run();

// Duplicate check result -> create / update / duplicate decision, review flags, Notion properties.
function run() {
  const cfg = $('Settings').first().json;
  const ctx = $('Parse & Match').first().json;
  const existing = ($input.first().json.results || [])[0] || null;
  const today = new Intl.DateTimeFormat('en-CA', { timeZone: cfg.timezone }).format(new Date());
  const decision = decideAction(ctx.parsed, existing, cfg, today);
  const a = ctx.attachment;
  const uploadDocument = decision.action !== 'duplicate' && !!a && (a.kind === 'pdf' || a.kind === 'image') && !ctx.parsed.attachmentTooLarge;
