    case 'phone_number':
      return p.phone_number;
    case 'checkbox':
      return p.checkbox;
    case 'date':
      return p.date ? p.date.start : null;
    case 'relation':
      return p.relation.map((r) => r.id);
    case 'files':
      return p.files.map((f) => f.name);
    case 'formula':
      return p.formula[p.formula.type];
    default:
      return null;
  }
}

function readCostPage(page) {
