// One call that turns an email + document text into a cost record ready for the
// duplicate check. Used by the "Parse & Match" Code node and the unit tests.
// Depends on extract.cjs, match.cjs, notion.cjs.

function toReferenceData(raw) {
  const rp = (page, name) => readProp(page.properties[name]);
  return {
    projects: (raw.projects || []).map((p) => ({
      id: p.id, name: rp(p, 'Project'), code: rp(p, 'Project Code'), address: rp(p, 'Site Address'),
      stage: rp(p, 'Stage'), pmId: (rp(p, 'Project Manager') || [])[0] || null,
    })),
    contacts: (raw.contacts || []).map((c) => ({ id: c.id, name: rp(c, 'Name'), company: rp(c, 'Company'), email: rp(c, 'Email'), type: rp(c, 'Type') })),
    employees: (raw.employees || []).map((e) => ({ id: e.id, name: rp(e, 'Name'), email: rp(e, 'Email'), role: rp(e, 'Role') })),
    orders: (raw.orders || []).map((o) => ({ id: o.id, po: rp(o, 'PO Number'), projectId: (rp(o, 'Project') || [])[0] || null })),
  };
}

/**
 * @param sub {{email:{from,fromName,subject,text,date,messageId}, attachment:{fileName,mimeType,kind,sizeBytes}|null, documentText:string}}
 * @param ref output of toReferenceData
 */
function prepareSubmission(sub, ref, cfg) {
  const email = sub.email || {};
  const attachment = sub.attachment || null;
  const documentText = sub.documentText || '';
  const f = extractFields({ subject: email.subject, body: email.text, documentText }, cfg);

  const supplier = matchSupplier(
    { fromEmail: email.from, fromName: email.fromName, subject: email.subject, body: email.text, documentText, labeledSupplier: f.labeledSupplier, firstLine: f.firstLine },
    ref.contacts, ref.employees, cfg
  );
  const pm = matchProject({ subject: email.subject, body: email.text, documentText, poNumber: f.poNumber }, ref.projects, ref.orders);
  const receivedAt = email.date ? new Date(email.date).toISOString() : new Date().toISOString();

  return {
    // extracted fields
    docRef: f.docRef,
    docType: f.docType,
    description: f.description,
    amount: f.amount,
    amountMethod: f.amountMethod,
    currency: f.currency,
    currencyMethod: f.currencyMethod,
    status: f.status,
    docDate: f.docDate || receivedAt.slice(0, 10),
    docDateSource: f.docDate ? 'document' : 'email',
    dueDate: f.dueDate,
    dueSource: f.dueSource,
    poNumber: f.poNumber,
    // matching
    supplierName: supplier.name,
    supplierContactId: supplier.contactId,
    supplierMethod: supplier.method,
    submittedBy: supplier.submittedBy,
    projectId: pm.project ? pm.project.id : null,
    projectName: pm.project ? pm.project.name : null,
    projectStage: pm.project ? pm.project.stage : null,
    projectPmId: pm.project ? pm.project.pmId : null,
    projectMethod: pm.method,
    projectCandidates: pm.candidates,
    // source
    fromEmail: email.from || null,
    fromName: email.fromName || null,
    subject: email.subject || '',
    messageId: email.messageId || null,
    receivedAt,
    sourceEmail: 'From: ' + (email.fromName ? email.fromName + ' <' + email.from + '>' : email.from || '?') + ' | Subject: ' + (email.subject || '') +
      ' | Received: ' + receivedAt + (attachment ? ' | File: ' + attachment.fileName : ' | No attachment'),
    attachmentKind: attachment ? attachment.kind : null,
    attachmentName: attachment ? attachment.fileName : null,
    pdfUnreadable: !!(attachment && attachment.kind === 'pdf' && !String(documentText).trim()),
    attachmentTooLarge: !!(attachment && attachment.sizeBytes && attachment.sizeBytes > cfg.maxUploadBytes),
  };
}

function findPeople(record, ref) {
  const project = record.projectId ? ref.projects.find((p) => p.id === record.projectId) : null;
  const pmId = record.projectPmId || (project ? project.pmId : null);
  const pick = (e) => (e ? { name: e.name, email: e.email } : null);
  return {
    projectManager: pick(pmId ? ref.employees.find((e) => e.id === pmId) : null),
    officeAdmin: pick(ref.employees.find((e) => e.role === 'Office Admin')),
    owner: pick(ref.employees.find((e) => e.role === 'Owner')),
  };
}


// ---- src/lib/decide.cjs ----
// Review rules, duplicate detection and create/update decisions.
// Depends on notion.cjs (COST, richText, readCostPage) - files are concatenated at build time.

const STATUS_RANK = { Unknown: 0, Unpaid: 1, 'Partially Paid': 2, Paid: 3 };

function lowerKey(s) {
  return String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
}

// Same shape as the keys already used in Part 2: "apex timber & frames|inv-77812".
function buildDedupeKey(r) {
  if (r.docRef) return lowerKey(r.supplierName) + '|' + lowerKey(r.docRef);
  return lowerKey(r.supplierName) + '|no-ref|' + (r.docDate || 'no-date') + '|' + (r.amount == null ? 'no-amount' : r.amount);
}

function summaryMonthOf(r) {
  return String(r.docDate || r.receivedAt || '').slice(0, 7) || null;
}

function buildSummaryKey(r) {
  const month = summaryMonthOf(r);
  if (!month) return null;
  return lowerKey(r.supplierName) + '|' + month + '|' + String(r.currency || '').toUpperCase();
}

function summaryTarget(r) {
  const key = r.summaryKey || buildSummaryKey(r);
  if (!key) return null;
  return { key, supplierName: r.supplierName, supplierContactId: r.supplierContactId || null, month: summaryMonthOf(r), currency: r.currency };
}

function money(n, cur) {
  if (n == null) return '-';
  return (cur ? cur + ' ' : '') + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

/** Rules that decide whether a (merged) cost record needs a human to look at it. */
function assessReview(r, cfg, today) {
  const reasons = [];
  if (r.amount == null) reasons.push('Amount not found');
  else if (r.amount <= 0) reasons.push('Zero or negative amount (credit note?)');
  if (!r.docRef) reasons.push('Invoice/receipt number not found - duplicate check falls back to supplier + date + amount');
  if (!r.docDate) reasons.push('Document date not found');
  else if (r.docDateSource === 'email') reasons.push('Document date not found - used email received date');
  if (!r.projectId) {
    reasons.push(r.projectCandidates && r.projectCandidates.length
      ? 'Several projects matched (' + r.projectCandidates.join(', ') + ') - pick the right one'
      : 'No project matched - add the project code (e.g. RIV-001) to the email');
  } else if (r.projectStage === 'Completed') reasons.push('Project "' + r.projectName + '" is marked Completed');
  if (r.supplierMethod === 'unknown') reasons.push('Supplier "' + r.supplierName + '" is not in Contacts (new supplier?)');
  if (r.status === 'Unknown') reasons.push('Payment status unclear - counted as unpaid');
  if (r.currency && r.currency !== cfg.baseCurrency) reasons.push('Currency is ' + r.currency + ' (not ' + cfg.baseCurrency + ')');
  if (r.amount != null && r.amount >= cfg.highValueThreshold) reasons.push('High value (>= ' + money(cfg.highValueThreshold, cfg.baseCurrency) + ') - check approval');
  if (r.status !== 'Paid' && r.dueDate && r.dueDate < today) reasons.push('Unpaid and overdue (due ' + r.dueDate + ')');
  if (r.attachmentKind === 'image') reasons.push('Photo/scanned receipt - no OCR, please check the fields manually');
  if (r.attachmentKind === 'other') reasons.push('Unsupported attachment type (' + (r.attachmentName || 'unknown') + ')');
  if (r.pdfUnreadable) reasons.push('PDF has no readable text (scanned?) - fields taken from the email only');
  if (r.attachmentTooLarge) reasons.push('Attachment larger than the Notion free-plan upload limit - not attached');
  return reasons;
}

function logLine(today, text) {
  return today + ' - ' + text;
}

function appendLog(existingLog, line) {
  const all = (existingLog ? existingLog + '\n' : '') + line;
  return all.length > 1900 ? '...' + all.slice(all.length - 1900) : all;
}

function costProperties(r, fields) {
  const P = {};
  const has = (k) => !fields || fields.includes(k);
  if (has('title')) P[COST.title] = { title: richText(r.title) };
  if (has('supplier')) P[COST.supplier] = { rich_text: richText(r.supplierName) };
  if (has('supplierContact')) P[COST.supplierContact] = { relation: r.supplierContactId ? [{ id: r.supplierContactId }] : [] };
  if (has('docRef')) P[COST.docRef] = { rich_text: richText(r.docRef) };
  if (has('docDate')) P[COST.docDate] = { date: r.docDate ? { start: r.docDate } : null };
  if (has('amount')) P[COST.amount] = { number: r.amount == null ? null : r.amount };
  if (has('currency')) P[COST.currency] = { select: r.currency ? { name: r.currency } : null };
  if (has('status')) P[COST.status] = { select: r.status ? { name: r.status } : null };
  if (has('dueDate')) P[COST.due] = { date: r.dueDate ? { start: r.dueDate } : null };
  if (has('project')) P[COST.project] = { relation: r.projectId ? [{ id: r.projectId }] : [] };
  if (has('dedupeKey')) P[COST.dedupeKey] = { rich_text: richText(r.dedupeKey) };
  if (has('summaryKey')) P[COST.summaryKey] = { rich_text: richText(r.summaryKey) };
  if (has('needsReview')) P[COST.needsReview] = { checkbox: !!r.needsReview };
  if (has('reviewReason')) P[COST.reviewReason] = { rich_text: richText(r.reviewReason) };
  if (has('sourceEmail')) P[COST.sourceEmail] = { rich_text: richText(r.sourceEmail) };
  if (has('messageId')) P[COST.messageId] = { rich_text: richText(r.messageId) };
  if (has('receivedAt')) P[COST.receivedAt] = { date: r.receivedAt ? { start: r.receivedAt } : null };
  if (has('submissions')) P[COST.submissions] = { number: r.submissions };
  if (has('updateLog')) P[COST.updateLog] = { rich_text: richText(r.updateLog) };
  return P;
}

/**
 * Decide what to do with a parsed submission.
 * @param parsed   output of the "Parse & Match" step (one document)
 * @param existingPage  Notion page with the same Dedupe Key, or null
 * @returns {{action:'create'|'update'|'duplicate', record, changes:string[], properties, recalc:string[], newReviewReasons:string[]}}
 */
function decideAction(parsed, existingPage, cfg, today) {
  const incoming = Object.assign({}, parsed);
  incoming.dedupeKey = buildDedupeKey(incoming);
  incoming.summaryKey = buildSummaryKey(incoming);

  if (!existingPage) {
    const reasons = assessReview(incoming, cfg, today);
    const record = Object.assign({}, incoming, {
      title: incoming.description || [incoming.docType, incoming.docRef, '-', incoming.supplierName].filter(Boolean).join(' '),
      needsReview: reasons.length > 0,
      reviewReason: reasons.join('; '),
      submissions: 1,
      updateLog: logLine(today, 'Created from email "' + (incoming.subject || '') + '" from ' + (incoming.fromEmail || 'unknown sender')),
    });
    return {
      action: 'create',
      record,
      changes: [],
      newReviewReasons: reasons,
      properties: costProperties(record),
      recalc: [summaryTarget(record)].filter(Boolean),
    };
  }

  const old = readCostPage(existingPage);
  if (!old.summaryKey) old.summaryKey = buildSummaryKey(old);
  const merged = Object.assign({}, old, {
    supplierMethod: parsed.supplierMethod === 'unknown' && old.supplierContactId ? 'existing' : parsed.supplierMethod,
    projectName: parsed.projectName,
    projectStage: parsed.projectStage,
    attachmentKind: parsed.attachmentKind,
    attachmentName: parsed.attachmentName,
    pdfUnreadable: parsed.pdfUnreadable,
    attachmentTooLarge: parsed.attachmentTooLarge,
    docDateSource: old.docDate ? 'document' : parsed.docDateSource,
  });
  const changes = [];
  const updateReasons = [];
  const changed = [];

  const setIf = (field, label, fmt) => {
    const nv = incoming[field];
    if (nv == null || nv === '' || nv === old[field]) return;
    changes.push(label + ': ' + (old[field] == null ? '(empty)' : fmt ? fmt(old[field]) : old[field]) + ' -> ' + (fmt ? fmt(nv) : nv));
    merged[field] = nv;
    changed.push(field);
  };

  if (incoming.amount != null && old.amount != null && incoming.amount !== old.amount) {
    updateReasons.push('Amount changed on resubmission: ' + money(old.amount) + ' -> ' + money(incoming.amount));
  }
  setIf('amount', 'Amount', (v) => money(v));
  if (incoming.currency && old.currency && incoming.currency !== old.currency && incoming.currencyMethod !== 'default') {
    updateReasons.push('Currency changed on resubmission: ' + old.currency + ' -> ' + incoming.currency);
    setIf('currency', 'Currency');
  } else if (!old.currency) setIf('currency', 'Currency');
  setIf('docDate', 'Document date');
  setIf('dueDate', 'Payment due');

  if (incoming.status && incoming.status !== 'Unknown' && incoming.status !== old.status) {
    if ((STATUS_RANK[incoming.status] || 0) >= (STATUS_RANK[old.status] || 0)) setIf('status', 'Payment status');
    else updateReasons.push('Newer document says "' + incoming.status + '" but record is "' + old.status + '" - kept "' + old.status + '"');
  }
  if (incoming.projectId && incoming.projectId !== old.projectId) {
    if (!old.projectId) { merged.projectId = incoming.projectId; changes.push('Project linked: ' + incoming.projectName); changed.push('project'); }
    else updateReasons.push('Resubmission points to a different project (' + incoming.projectName + ') - not changed');
  }
  if (!old.supplierContactId && incoming.supplierContactId) { merged.supplierContactId = incoming.supplierContactId; changed.push('supplierContact'); }

  merged.summaryKey = buildSummaryKey(merged);
  merged.submissions = (old.submissions || 1) + 1;
  merged.messageId = incoming.messageId;

  if (!changes.length && !updateReasons.length) {
    merged.updateLog = appendLog(old.updateLog, logLine(today, 'Duplicate submission ignored - no changes (' + (incoming.messageId || 'no message id') + ')'));
    return {
      action: 'duplicate',
      record: merged,
      changes: [],
      newReviewReasons: [],
      properties: costProperties(merged, ['submissions', 'updateLog', 'messageId']),
      recalc: [summaryTarget(merged)].filter(Boolean),
    };
  }

  const ruleReasons = assessReview(merged, cfg, today);
  const reasons = [...new Set([...updateReasons, ...ruleReasons])];
  merged.needsReview = old.needsReview || reasons.length > 0;
  merged.reviewReason = reasons.length ? reasons.join('; ') : old.reviewReason;
  merged.updateLog = appendLog(
    old.updateLog,
    logLine(today, 'Resubmission "' + (incoming.subject || '') + '": ' + (changes.length ? changes.join('; ') : 'no field changes') +
      (updateReasons.length ? ' | flagged: ' + updateReasons.join('; ') : ''))
  );
  return {
    action: 'update',
    record: merged,
    changes,
    newReviewReasons: reasons,
    properties: costProperties(merged, [...changed, 'summaryKey', 'needsReview', 'reviewReason', 'submissions', 'updateLog', 'messageId']),
    recalc: [summaryTarget(merged), old.summaryKey !== merged.summaryKey ? summaryTarget(old) : null].filter(Boolean),
  };
}


// ---- src/lib/summary.cjs ----
// Supplier Monthly Summary: totals are always recomputed from the cost records
// (never incremented), so re-running the workflow can't double-count.
// Depends on notion.cjs (richText, readCostPage).

const SUMMARY = {
  title: 'Summary',
  supplier: 'Supplier',
  supplierName: 'Supplier Name',
  month: 'Month',
  monthKey: 'Month Key',
  currency: 'Currency',
  paid: 'Total Paid',
  unpaid: 'Total Unpaid',
  count: 'Cost Count',
  key: 'Summary Key',
  updated: 'Last Recalculated',
};

function round2(n) {
  return Math.round(n * 100) / 100;
}

/** pages: Notion cost pages sharing one Summary Key. Paid counts as paid; Unpaid, Partially Paid and Unknown count as unpaid. */
function computeTotals(pages) {
  let paid = 0, unpaid = 0, count = 0, unpaidCount = 0;
  const seen = new Set();
  for (const page of pages) {
    if (!page || seen.has(page.id) || page.archived || page.in_trash) continue;
    seen.add(page.id);
    const c = readCostPage(page);
    if (c.amount == null) { count++; continue; }
    count++;
    if (c.status === 'Paid') paid += c.amount;
    else { unpaid += c.amount; unpaidCount++; }
  }
  return { paid: round2(paid), unpaid: round2(unpaid), total: round2(paid + unpaid), count, unpaidCount };
}

function monthLabel(month) {
  const [y, m] = String(month).split('-').map(Number);
  const names = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return names[m - 1] + ' ' + y;
}

function summaryProperties(target, totals, nowIso) {
  const P = {};
  P[SUMMARY.title] = { title: richText(target.supplierName + ' - ' + monthLabel(target.month) + ' (' + target.currency + ')') };
  P[SUMMARY.supplier] = { relation: target.supplierContactId ? [{ id: target.supplierContactId }] : [] };
  P[SUMMARY.supplierName] = { rich_text: richText(target.supplierName) };
  P[SUMMARY.month] = { date: { start: target.month + '-01' } };
  P[SUMMARY.monthKey] = { rich_text: richText(target.month) };
  P[SUMMARY.currency] = { select: { name: target.currency } };
  P[SUMMARY.paid] = { number: totals.paid };
  P[SUMMARY.unpaid] = { number: totals.unpaid };
  P[SUMMARY.count] = { number: totals.count };
  P[SUMMARY.key] = { rich_text: richText(target.key) };
  P[SUMMARY.updated] = { date: { start: nowIso } };
  return P;
}


// ---- src/lib/notify.cjs ----
// Builds the notification email. In demo mode every email goes to cfg.demoRecipient,
// with a banner naming who would receive it in production.
// Depends on decide.cjs (money) and summary.cjs (monthLabel).

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/**
 * @param d {{action, record, changes, newReviewReasons, notionUrl, summaries:[{target,totals}]}}
 * @param people {{projectManager, officeAdmin, owner}}  each {name,email} or null
 */
function buildNotification(d, people, cfg) {
  const r = d.record;
  const needsReview = d.newReviewReasons.length > 0;
  if (d.action === 'duplicate') return { send: false, reason: 'duplicate - nothing changed' };

  const intended = [];
  const add = (p, why) => { if (p && p.email && !intended.some((x) => x.email === p.email)) intended.push({ name: p.name, email: p.email, why }); };
  add(people.projectManager, 'project manager');
  if (needsReview) { add(people.officeAdmin, 'office admin - review'); add(people.owner, 'owner - review'); }
  if (!intended.length) { add(people.officeAdmin, 'office admin (no project manager)'); add(people.owner, 'owner'); }

  const what = d.action === 'create' ? 'Cost recorded' : 'Cost updated';
  const subjectCore = [r.supplierName, r.docRef, money(r.amount, r.currency), r.projectName || 'NO PROJECT'].filter(Boolean).join(' | ');
  const subject = (cfg.demoMode ? '[DEMO] ' : '') + (needsReview ? 'Needs review - ' : '') + what + ': ' + subjectCore;

  const row = (k, v) => '<tr><td style="padding:4px 12px 4px 0;color:#555">' + esc(k) + '</td><td style="padding:4px 0"><b>' + esc(v) + '</b></td></tr>';
  const banner = cfg.demoMode
    ? '<div style="background:#fff3cd;border:1px solid #e0b100;padding:10px 14px;margin-bottom:16px;border-radius:6px">' +
      '<b>This is a demo.</b> In production this email would be sent to: ' +
      intended.map((p) => esc(p.name) + ' &lt;' + esc(p.email) + '&gt; (' + esc(p.why) + ')').join(', ') + '</div>'
    : '';
  const review = needsReview
    ? '<div style="background:#fdecea;border:1px solid #d93025;padding:10px 14px;margin:16px 0;border-radius:6px"><b>Needs review:</b><ul style="margin:6px 0 0 18px;padding:0">' +
      d.newReviewReasons.map((x) => '<li>' + esc(x) + '</li>').join('') + '</ul></div>'
    : '';
  const changes = d.changes.length ? '<p><b>Changes from the resubmission:</b><br>' + d.changes.map(esc).join('<br>') + '</p>' : '';
  const sums = (d.summaries || []).map((s) =>
    '<li>' + esc(s.target.supplierName) + ', ' + esc(monthLabel(s.target.month)) + ': paid ' + esc(money(s.totals.paid, s.target.currency)) +
    ', unpaid ' + esc(money(s.totals.unpaid, s.target.currency)) + ' (' + s.totals.count + ' costs)</li>').join('');

  const html =
    '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#222;max-width:640px">' + banner +
    '<h2 style="margin:0 0 8px">' + esc(what) + (needsReview ? ' - needs review' : '') + '</h2>' +
    '<table style="border-collapse:collapse">' +
    row('Supplier', r.supplierName) + row('Document', [r.docType, r.docRef].filter(Boolean).join(' ') || '-') +
    row('Project', r.projectName || 'Not matched') + row('Amount', money(r.amount, r.currency)) +
    row('Status', r.status) + row('Document date', r.docDate || '-') + row('Payment due', r.dueDate || '-') +
    row('Submitted by', r.fromEmail || '-') + '</table>' + review + changes +
    (sums ? '<p><b>Supplier Monthly Summary (recalculated):</b></p><ul>' + sums + '</ul>' : '') +
    (d.notionUrl ? '<p><a href="' + esc(d.notionUrl) + '">Open the cost record in Notion</a></p>' : '') +
    '<p style="color:#888;font-size:12px">Sent automatically by the Kevin Build Co. cost intake workflow (n8n).</p></div>';

  return {
    send: true,
    to: cfg.demoMode ? cfg.demoRecipient : intended.map((p) => p.email).join(', '),
    intendedRecipients: intended,
    subject,
    html,
    needsReview,
  };
}


return run();

// One result line per document; collected by the loop and returned to the webhook caller.
const ctx = $('Build Notification').first().json;
const input = $input.first().json;
const r = ctx.decision.record;
const n = ctx.notification;
// A real send returns the SMTP result; a disabled email node just passes our item through.
const delivered = Array.isArray(input.accepted) && input.accepted.length > 0;
const sendError = input.error ? String(input.error.message || input.error) : !delivered && n.send ? 'email node disabled or no SMTP credential' : undefined;
return [{
  json: {
    submissionId: ctx.submissionId,
    file: ctx.attachment ? ctx.attachment.fileName : null,
    action: ctx.decision.action,
    supplier: r.supplierName,
    docRef: r.docRef || null,
    amount: r.amount,
    currency: r.currency,
    status: r.status,
    docDate: r.docDate || null,
    dueDate: r.dueDate || null,
    project: r.projectName || null,
    needsReview: !!r.needsReview,
    reviewReasons: ctx.decision.newReviewReasons,
    changes: ctx.decision.changes,
    submissions: r.submissions,
    notionUrl: ctx.notionUrl,
    summaries: ctx.summaries.map((s) => ({ key: s.target.key, paid: s.totals.paid, unpaid: s.totals.unpaid, count: s.totals.count })),
    notification: n.send
      ? { sent: delivered, to: n.to, subject: n.subject, intendedRecipients: n.intendedRecipients.map((p) => p.email), error: sendError }
      : { sent: false, reason: n.reason },
  },
}];

// Final response for the test webhook: what happened to every document in this run.
const results = $input.all().map((i) => i.json);
return [{ json: { processed: results.length, results } }];
